function storyForm11(){ return state.questPack?.storyForm11 || state.storyForm11 || null; }

function pickUnifiedStoryWinner() {
  const ladder = storyForm11()?.unifiedStreetStoryLayer?.priorityLadder || [];
  for (const step of ladder) {
    if (whenOk(step.when)) return step.id;
  }
  return null;
}

function volumeStreetBeatHtml() {
  const props = storyForm11()?.volumeStreetBeatProps || [];
  const hit = props.filter(p => whenOk(p.when)).sort((a,b)=>0)[0]; // first matching by list order = beat order
  // prefer highest beat: reverse scan
  for (let i = props.length-1; i >= 0; i--) if (whenOk(props[i].when)) {
    const p = props[i];
    return (state.locale==="tr" && p.htmlTr) ? p.htmlTr : p.html;
  }
  return "";
}

function mqStreetChipHtml() {
  const chips = storyForm11()?.mqStreetChips || [];
  const hit = chips.find(c => whenOk(c.when));
  if (!hit) return "";
  const t = hit.chip[state.locale] || hit.chip.en;
  return `<div class="rp-mq-street-chip" data-testid="${hit.testId}">${t}</div>`;
}

// renderStreet:
const winner = pickUnifiedStoryWinner();
document.body.classList.toggle("rp-story-one-signal", !!winner);
// paint only winner's prop family + mq chip + one bubble
